<?php require_login(['admin']); $pdo=db(); $action=$_GET['action']??'list'; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$d=[trim($_POST['employee_no']),trim($_POST['name']),trim($_POST['subject']),trim($_POST['designation']),trim($_POST['phone']),trim($_POST['email']),($_POST['joining_date']?:null),(float)$_POST['salary'],$_POST['status']];if($id){$s=$pdo->prepare('UPDATE teachers SET employee_no=?,name=?,subject=?,designation=?,phone=?,email=?,joining_date=?,salary=?,status=? WHERE id=?');$s->execute([...$d,$id]);flash('success','Teacher updated.');}else{$s=$pdo->prepare('INSERT INTO teachers(employee_no,name,subject,designation,phone,email,joining_date,salary,status) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute($d);flash('success','Teacher added.');}redirect('index.php?page=teachers');}if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM teachers WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Teacher deleted.');redirect('index.php?page=teachers');}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM teachers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();$action='new';}$rows=$pdo->query('SELECT * FROM teachers ORDER BY id DESC')->fetchAll();
?><div class="toolbar"><div></div><a class="btn primary" href="index.php?page=teachers&action=new">＋ Add Teacher</a></div><?php if($action==='new'):?><section class="panel"><div class="panel-head"><h2><?=$edit?'Edit':'Add'?> Teacher</h2><a href="index.php?page=teachers">Cancel</a></div><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Employee No<input required name="employee_no" value="<?=e($edit['employee_no']??'EMP-'.rand(100,999))?>"></label><label>Name<input required name="name" value="<?=e($edit['name']??'')?>"></label><label>Subject<input name="subject" value="<?=e($edit['subject']??'')?>"></label><label>Designation<input name="designation" value="<?=e($edit['designation']??'Teacher')?>"></label><label>Phone<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label>Joining Date<input type="date" name="joining_date" value="<?=e($edit['joining_date']??'')?>"></label><label>Salary<input type="number" step="0.01" name="salary" value="<?=e($edit['salary']??0)?>"></label><label>Status<select name="status"><option>active</option><option>inactive</option></select></label><button class="btn primary wide">Save Teacher</button></form></section><?php else:?><section class="panel"><div class="panel-head"><h2>Teachers</h2></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Name</th><th>Subject</th><th>Designation</th><th>Phone</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['employee_no'])?></td><td><?=e($r['name'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['designation'])?></td><td><?=e($r['phone'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><a class="action" href="index.php?page=teachers&edit=<?=$r['id']?>">Edit</a> <a class="action danger-text" data-confirm="Delete teacher?" href="index.php?page=teachers&delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
